import{_ as t,o as a,c as r,a2 as d}from"./chunks/framework.CqGPl1zp.js";const o="/newx-doc/assets/schema.D8iy38zz.png",s="/newx-doc/assets/views.ChA8lr6L.png",c="/newx-doc/assets/api.BpvplkLp.png",v=JSON.parse('{"title":"开发规范","description":"","frontmatter":{},"headers":[],"relativePath":"vben5/dev-spec.md","filePath":"vben5/dev-spec.md","lastUpdated":null}'),i={name:"vben5/dev-spec.md"};function n(l,e,p,b,u,m){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="开发规范" tabindex="-1">开发规范 <a class="header-anchor" href="#开发规范" aria-label="Permalink to &quot;开发规范&quot;">​</a></h1><p>本项目基于 <a href="https://github.com/vbenjs/vue-vben-admin" target="_blank" rel="noreferrer">Vben Admin 5.x</a> 进行二次开发，采用 Vue 3 + TypeScript + Vite 技术栈，支持 Ant Design Vue（antd）、Element Plus（ele）、Naive 等主流 UI 库。</p><p>官方文档</p><p>强烈建议先阅读 Vben Admin 官方文档，了解框架的基础概念和使用方式：</p><ul><li><a href="https://doc.vben.pro/guide/introduction/vben.html" target="_blank" rel="noreferrer">《关于 Vben Admin》</a> - 了解框架特点、浏览器支持、如何参与贡献等</li><li><a href="https://doc.vben.pro/guide/introduction/why.html" target="_blank" rel="noreferrer">《为什么选择我们?》</a> - 了解框架历程、单元测试、代码质量与规范等</li><li><a href="https://doc.vben.pro/guide/essentials/concept.html" target="_blank" rel="noreferrer">《基础概念》</a> - 了解大仓、应用、包、别名等核心概念</li><li><a href="https://doc.vben.pro/guide/essentials/development.html" target="_blank" rel="noreferrer">《本地开发》</a> - 了解如何启动和开发项目</li><li><a href="https://doc.vben.pro/guide/essentials/settings.html" target="_blank" rel="noreferrer">《配置》</a> - 了解环境变量配置、生产环境动态配置、偏好设置等</li></ul><h2 id="_0-实战案例" tabindex="-1">0. 实战案例 <a class="header-anchor" href="#_0-实战案例" aria-label="Permalink to &quot;0. 实战案例&quot;">​</a></h2><p>本小节，提供大家开发管理后台的功能时，最常用的分页列表、树形列表、新增与修改的表单弹窗、详情表单弹窗的实战案例。</p><h3 id="_0-1-分页列表" tabindex="-1">0.1 分页列表 <a class="header-anchor" href="#_0-1-分页列表" aria-label="Permalink to &quot;0.1 分页列表&quot;">​</a></h3><p>可参考 [系统管理 -&gt; 岗位管理] 菜单：</p><table tabindex="0"><thead><tr><th>文件类型</th><th>antd 版本</th><th>ele 版本</th></tr></thead><tbody><tr><td>API 接口</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-antd/src/api/system/post/index.ts" target="_blank" rel="noreferrer"><code>apps/web-antd/src/api/system/post/index.ts</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-ele/src/api/system/post/index.ts" target="_blank" rel="noreferrer"><code>apps/web-ele/src/api/system/post/index.ts</code></a></td></tr><tr><td>列表界面</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-antd/src/views/system/post/index.vue" target="_blank" rel="noreferrer"><code>apps/web-antd/src/views/system/post/index.vue</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-ele/src/views/system/post/index.vue" target="_blank" rel="noreferrer"><code>apps/web-ele/src/views/system/post/index.vue</code></a></td></tr><tr><td>表单界面</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-antd/src/views/system/post/modules/form.vue" target="_blank" rel="noreferrer"><code>apps/web-antd/src/views/system/post/modules/form.vue</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-ele/src/views/system/post/modules/form.vue" target="_blank" rel="noreferrer"><code>apps/web-ele/src/views/system/post/modules/form.vue</code></a></td></tr><tr><td>数据配置</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-antd/src/views/system/post/data.ts" target="_blank" rel="noreferrer"><code>apps/web-antd/src/views/system/post/data.ts</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-ele/src/views/system/post/data.ts" target="_blank" rel="noreferrer"><code>apps/web-ele/src/views/system/post/data.ts</code></a></td></tr></tbody></table><p>为什么界面拆成列表和表单两个 Vue 文件？</p><p>每个 Vue 文件，只实现一个功能，更简洁，维护性更好，Git 代码冲突概率低。</p><p>具体可见本文的「3.3 页面级组件」。</p><p>其中，<code>data.ts</code> 用于定义表格列配置、搜索表单配置、新增/修改表单配置等，将配置与业务逻辑分离，提高代码可维护性。整体结构，如下图所示：</p><p><img src="'+o+'" alt="岗位管理代码结构"></p><ul><li><a href="https://doc.vben.pro/components/common-ui/vben-vxe-table.html" target="_blank" rel="noreferrer">Vben Vxe Table 表格</a></li><li><a href="https://doc.vben.pro/components/common-ui/vben-form.html" target="_blank" rel="noreferrer">Vben Form 表单</a></li><li><a href="https://doc.vben.pro/components/common-ui/vben-modal.html" target="_blank" rel="noreferrer">Vben Modal 模态框</a></li></ul><hr><p>另外，项目在 <code>src/adapter</code> 目录下对表单和表格进行了扩展配置：</p><table tabindex="0"><thead><tr><th>文件类型</th><th>antd 版本</th><th>ele 版本</th></tr></thead><tbody><tr><td>表单适配器</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-antd/src/adapter/form.ts" target="_blank" rel="noreferrer"><code>apps/web-antd/src/adapter/form.ts</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-ele/src/adapter/form.ts" target="_blank" rel="noreferrer"><code>apps/web-ele/src/adapter/form.ts</code></a></td></tr><tr><td>表格适配器</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-antd/src/adapter/vxe-table.ts" target="_blank" rel="noreferrer"><code>apps/web-antd/src/adapter/vxe-table.ts</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-ele/src/adapter/vxe-table.ts" target="_blank" rel="noreferrer"><code>apps/web-ele/src/adapter/vxe-table.ts</code></a></td></tr></tbody></table><p>① <code>form.ts</code> 中定义了自定义校验规则，可在表单 Schema 的 <code>rules</code> 属性中使用：</p><ul><li><code>required</code> - 输入项必填校验</li><li><code>selectRequired</code> - 选择项必填校验</li><li><code>mobile</code> - 手机号格式校验（非必填）</li><li><code>mobileRequired</code> - 手机号格式校验（必填）</li></ul><p>② <code>vxe-table.ts</code> 中定义了自定义单元格渲染器和格式化器：</p><p>单元格渲染器（<code>cellRender</code>）：</p><ul><li><code>CellImage</code> - 图片渲染</li><li><code>CellImages</code> - 多图片渲染</li><li><code>CellLink</code> - 链接按钮</li><li><code>CellTag</code> - 标签渲染</li><li><code>CellTags</code> - 多标签渲染</li><li><code>CellDict</code> - 字典标签渲染，如 <code>cellRender: { name: &#39;CellDict&#39;, props: { type: &#39;system_user_sex&#39; } }</code></li><li><code>CellSwitch</code> - 开关渲染，支持异步切换</li><li><code>CellOperation</code> - 操作按钮渲染，如 <code>cellRender: { name: &#39;CellOperation&#39;, options: [&#39;edit&#39;, &#39;delete&#39;] }</code></li></ul><p>格式化器（<code>formatter</code>）：</p><ul><li><code>formatPast2</code> - 相对时间格式化（如&quot;3 天前&quot;）</li><li><code>formatAmount3</code> - 数量格式化，保留 3 位小数</li><li><code>formatAmount2</code> - 数量格式化，保留 2 位小数</li><li><code>formatFenToYuanAmount</code> - 分转元格式化</li><li><code>formatFileSize</code> - 文件大小格式化</li></ul><h3 id="_0-2-树形列表" tabindex="-1">0.2 树形列表 <a class="header-anchor" href="#_0-2-树形列表" aria-label="Permalink to &quot;0.2 树形列表&quot;">​</a></h3><p>可参考 [系统管理 -&gt; 部门管理] 菜单：</p><table tabindex="0"><thead><tr><th>文件类型</th><th>antd 版本</th><th>ele 版本</th></tr></thead><tbody><tr><td>API 接口</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-antd/src/api/system/dept/index.ts" target="_blank" rel="noreferrer"><code>apps/web-antd/src/api/system/dept/index.ts</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-ele/src/api/system/dept/index.ts" target="_blank" rel="noreferrer"><code>apps/web-ele/src/api/system/dept/index.ts</code></a></td></tr><tr><td>列表界面</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-antd/src/views/system/dept/index.vue" target="_blank" rel="noreferrer"><code>apps/web-antd/src/views/system/dept/index.vue</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-ele/src/views/system/dept/index.vue" target="_blank" rel="noreferrer"><code>apps/web-ele/src/views/system/dept/index.vue</code></a></td></tr><tr><td>表单界面</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-antd/src/views/system/dept/modules/form.vue" target="_blank" rel="noreferrer"><code>apps/web-antd/src/views/system/dept/modules/form.vue</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-ele/src/views/system/dept/modules/form.vue" target="_blank" rel="noreferrer"><code>apps/web-ele/src/views/system/dept/modules/form.vue</code></a></td></tr><tr><td>数据配置</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-antd/src/views/system/dept/data.ts" target="_blank" rel="noreferrer"><code>apps/web-antd/src/views/system/dept/data.ts</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-ele/src/views/system/dept/data.ts" target="_blank" rel="noreferrer"><code>apps/web-ele/src/views/system/dept/data.ts</code></a></td></tr></tbody></table><h3 id="_0-3-详情弹窗" tabindex="-1">0.3 详情弹窗 <a class="header-anchor" href="#_0-3-详情弹窗" aria-label="Permalink to &quot;0.3 详情弹窗&quot;">​</a></h3><p>可参考 [基础设施 -&gt; API 日志 -&gt; 访问日志] 菜单：</p><table tabindex="0"><thead><tr><th>文件类型</th><th>antd 版本</th><th>ele 版本</th></tr></thead><tbody><tr><td>列表界面</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-antd/src/views/infra/apiAccessLog/index.vue" target="_blank" rel="noreferrer"><code>apps/web-antd/src/views/infra/apiAccessLog/index.vue</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-ele/src/views/infra/apiAccessLog/index.vue" target="_blank" rel="noreferrer"><code>apps/web-ele/src/views/infra/apiAccessLog/index.vue</code></a></td></tr><tr><td>详情弹窗</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-antd/src/views/infra/apiAccessLog/modules/detail.vue" target="_blank" rel="noreferrer"><code>apps/web-antd/src/views/infra/apiAccessLog/modules/detail.vue</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-ele/src/views/infra/apiAccessLog/modules/detail.vue" target="_blank" rel="noreferrer"><code>apps/web-ele/src/views/infra/apiAccessLog/modules/detail.vue</code></a></td></tr><tr><td>数据配置</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-antd/src/views/infra/apiAccessLog/data.ts" target="_blank" rel="noreferrer"><code>apps/web-antd/src/views/infra/apiAccessLog/data.ts</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-ele/src/views/infra/apiAccessLog/data.ts" target="_blank" rel="noreferrer"><code>apps/web-ele/src/views/infra/apiAccessLog/data.ts</code></a></td></tr></tbody></table><p>详情弹窗，使用 <code>useVbenModal</code> 和 <code>useDescription</code> 组合实现，<code>data.ts</code> 中通过 <code>useDetailSchema()</code> 定义详情字段的展示配置。</p><h2 id="_1-view-页面" tabindex="-1">1. view 页面 <a class="header-anchor" href="#_1-view-页面" aria-label="Permalink to &quot;1. view 页面&quot;">​</a></h2><p>在 <a href="https://github.com/yudaocode/yudao-ui-admin-vben/tree/master/apps/web-antd/src/views" target="_blank" rel="noreferrer"><code>apps/web-antd/src/views</code></a> 或 <a href="https://github.com/yudaocode/yudao-ui-admin-vben/tree/master/apps/web-ele/src/views" target="_blank" rel="noreferrer"><code>apps/web-ele/src/views</code></a> 目录下，每个模块对应一个目录，它的所有功能的 <code>.vue</code> 都放在该目录里。</p><p><img src="'+s+'" alt="views 目录结构"></p><p>一般来说，一个路由对应一个 <code>index.vue</code> 文件，表单弹窗等组件放在 <code>modules</code> 子目录下。</p><h2 id="_2-api-请求" tabindex="-1">2. api 请求 <a class="header-anchor" href="#_2-api-请求" aria-label="Permalink to &quot;2. api 请求&quot;">​</a></h2><p>在 <a href="https://github.com/yudaocode/yudao-ui-admin-vben/tree/master/apps/web-antd/src/api" target="_blank" rel="noreferrer"><code>apps/web-antd/src/api</code></a> 目录下，每个模块对应一个目录，包含该模块的所有 API 文件。</p><p><img src="'+c+'" alt="api 目录结构"></p><p>每个 API 文件通常包含：</p><ul><li>API 方法：调用 <code>requestClient</code> 发起对后端 RESTful API 的请求</li><li><code>interface</code> 类型：定义 API 的请求参数和返回结果的类型，对应后端的 VO 类型</li></ul><h3 id="_2-1-请求封装" tabindex="-1">2.1 请求封装 <a class="header-anchor" href="#_2-1-请求封装" aria-label="Permalink to &quot;2.1 请求封装&quot;">​</a></h3><p>项目使用 <code>@vben/request</code> 包进行请求封装，配置文件位于 <a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-antd/src/api/request.ts" target="_blank" rel="noreferrer"><code>apps/web-antd/src/api/request.ts</code></a> 。</p><p>官方文档</p><p>详细的请求配置和使用方式，请参考：<a href="https://doc.vben.pro/guide/essentials/server.html" target="_blank" rel="noreferrer">服务端交互与数据 Mock</a></p><p>请求封装中包含了以下核心功能：</p><ul><li>租户支持：自动在请求头中添加 <code>tenant-id</code> 租户编号</li><li>访问令牌：自动在请求头中添加 <code>Authorization</code> Bearer Token</li><li>刷新令牌：当访问令牌过期时，自动使用 <code>refreshToken</code> 刷新令牌</li><li>API 加密：支持请求数据加密和响应数据解密</li><li>错误处理：统一的错误消息提示和 401 未登录处理</li></ul><h2 id="_3-component-组件" tabindex="-1">3. component 组件 <a class="header-anchor" href="#_3-component-组件" aria-label="Permalink to &quot;3. component 组件&quot;">​</a></h2><h3 id="_3-1-全局组件" tabindex="-1">3.1 全局组件 <a class="header-anchor" href="#_3-1-全局组件" aria-label="Permalink to &quot;3.1 全局组件&quot;">​</a></h3><p>① Vben Admin 5.x 提供了丰富的通用组件，位于 <code>packages/effects/common-ui</code> 目录下，常用组件包括 VbenVxeTable（表格）、VbenForm（表单）、VbenModal（弹窗）等等。</p><p>② 每个 UI 库（antd、ele、naive）也有自己的全局组件，放在各自应用的 <code>src/components</code> 目录下，例如：</p><ul><li>antd 版本：<a href="https://github.com/yudaocode/yudao-ui-admin-vben/tree/master/apps/web-antd/src/components" target="_blank" rel="noreferrer"><code>apps/web-antd/src/components</code></a></li><li>ele 版本：<a href="https://github.com/yudaocode/yudao-ui-admin-vben/tree/master/apps/web-ele/src/components" target="_blank" rel="noreferrer"><code>apps/web-ele/src/components</code></a></li></ul><p>这些组件包括：字典标签（dict-tag）、文件上传（upload）、富文本编辑器（tinymce）、图片裁剪（cropper）等，可供整个应用使用。</p><hr><p>更多说明，可见 系统组件 文档。</p><h3 id="_3-2-模块级组件" tabindex="-1">3.2 模块级组件 <a class="header-anchor" href="#_3-2-模块级组件" aria-label="Permalink to &quot;3.2 模块级组件&quot;">​</a></h3><p>每个模块可以有自己的 <code>components</code> 目录，用于存放可被该模块下多个页面复用的组件。例如：</p><table tabindex="0"><thead><tr><th>组件目录</th><th>antd 版本</th><th>ele 版本</th></tr></thead><tbody><tr><td>部门组件</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/tree/master/apps/web-antd/src/views/system/dept/components" target="_blank" rel="noreferrer"><code>apps/web-antd/src/views/system/dept/components</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/tree/master/apps/web-ele/src/views/system/dept/components" target="_blank" rel="noreferrer"><code>apps/web-ele/src/views/system/dept/components</code></a></td></tr><tr><td>用户组件</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/tree/master/apps/web-antd/src/views/system/user/components" target="_blank" rel="noreferrer"><code>apps/web-antd/src/views/system/user/components</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/tree/master/apps/web-ele/src/views/system/user/components" target="_blank" rel="noreferrer"><code>apps/web-ele/src/views/system/user/components</code></a></td></tr></tbody></table><h3 id="_3-3-页面内组件" tabindex="-1">3.3 页面内组件 <a class="header-anchor" href="#_3-3-页面内组件" aria-label="Permalink to &quot;3.3 页面内组件&quot;">​</a></h3><p>每个页面的私有组件，放在 <code>views</code> 目录下对应页面的 <code>modules</code> 目录下，仅供当前页面使用，不对外暴露。</p><table tabindex="0"><thead><tr><th>组件示例</th><th>antd 版本</th><th>ele 版本</th></tr></thead><tbody><tr><td>岗位表单</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-antd/src/views/system/post/modules/form.vue" target="_blank" rel="noreferrer"><code>apps/web-antd/src/views/system/post/modules/form.vue</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-ele/src/views/system/post/modules/form.vue" target="_blank" rel="noreferrer"><code>apps/web-ele/src/views/system/post/modules/form.vue</code></a></td></tr><tr><td>日志详情</td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-antd/src/views/infra/apiAccessLog/modules/detail.vue" target="_blank" rel="noreferrer"><code>apps/web-antd/src/views/infra/apiAccessLog/modules/detail.vue</code></a></td><td><a href="https://github.com/yudaocode/yudao-ui-admin-vben/blob/master/apps/web-ele/src/views/infra/apiAccessLog/modules/detail.vue" target="_blank" rel="noreferrer"><code>apps/web-ele/src/views/infra/apiAccessLog/modules/detail.vue</code></a></td></tr></tbody></table><h2 id="_4-style-样式" tabindex="-1">4. style 样式 <a class="header-anchor" href="#_4-style-样式" aria-label="Permalink to &quot;4. style 样式&quot;">​</a></h2><p>项目使用 <a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS</a> 作为主要的样式方案，可参考如下文档：</p><ul><li><a href="https://doc.vben.pro/guide/essentials/styles.html" target="_blank" rel="noreferrer">《Vben 官方文档 —— 样式》</a></li><li><a href="https://doc.vben.pro/guide/project/tailwindcss.html" target="_blank" rel="noreferrer">《Vben 官方文档 —— Tailwind CSS》</a></li></ul><h2 id="_5-项目规范" tabindex="-1">5. 项目规范 <a class="header-anchor" href="#_5-项目规范" aria-label="Permalink to &quot;5. 项目规范&quot;">​</a></h2><p>可参考 <a href="https://doc.vben.pro/guide/project/standard.html" target="_blank" rel="noreferrer">《Vben 官方文档 —— 规范》</a></p>',67)])])}const f=t(i,[["render",n]]);export{v as __pageData,f as default};
